            unserved.remove(bc)
            if rem is not None:
                rem -= dmap.get(bc, 0)
        routes.append(r)

    def improve_route(r):
        changed = True
        while changed and len(r) > 2:
            changed = False
            base = rcost(r)
            bi = bj = None
            best = 0
            for i in range(len(r)):
                x = r[i]
                t = r[:i] + r[i + 1:]
                for j in range(len(t) + 1):
                    nr = t[:j] + [x] + t[j:]
                    d = rcost(nr) - base
                    if d < best:
                        best = d
                        bi, bj = i, j
            if bi is not None:
                x = r.pop(bi)
                if bj > bi:
                    bj -= 1
                r.insert(bj, x)
                changed = True
                continue
            for i in range(len(r)):
                for j in range(i + 1, len(r)):
                    nr = r[:i] + r[i:j + 1][::-1] + r[j + 1:]
                    if rcost(nr) + 1e-12 < base:
                        r[:] = nr
                        changed = True
                        break
                if changed:
                    break
        return r

    routes = [improve_route(r[:]) for r in routes if r]

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    for c in list(seen.keys()):
        while seen[c] > 1:
            for r in routes:
                if c in r and seen[c] > 1:
                    r.remove(c)
                    seen[c] -= 1
                    break
    routes = [r for r in routes if r]

    missing = [c for c in customers if seen.get(c, 0) == 0]
    for c in missing:
        dem = dmap.get(c, 0)
        best = None
        for i, r in enumerate(routes):
            if cap is not None and load(r) + dem > cap:
                continue
            p, dlt = best_ins(r, c)
            s = (dlt, i, p)
            if best is None or s < best[0]:
                best = (s, i, p)
        if best is None:
            routes.append([c])
        else:
            routes[best[1]].insert(best[2], c)

    routes = [r for r in routes if r]
    routes.sort(key=lambda r: (r[0], len(r), rcost(r)))
    return routes
